import{_ as t,c as a,o,ag as r}from"./chunks/framework.DZ_cNctr.js";const i="/docs/screenshots/mrxs-slide.webp",u=JSON.parse('{"title":"3DHISTECH MRXS Slides in the Browser","titleTemplate":"Find Nuclei: :title","description":"Find Nuclei opens 3DHISTECH Pannoramic MRXS slides in your browser, from a folder, a zip or a link. Free, nothing to install or convert.","frontmatter":{"title":"3DHISTECH MRXS Slides in the Browser","titleTemplate":"Find Nuclei: :title","description":"Find Nuclei opens 3DHISTECH Pannoramic MRXS slides in your browser, from a folder, a zip or a link. Free, nothing to install or convert."},"headers":[],"relativePath":"guides/mrxs.md","filePath":"guides/mrxs.md"}'),s={name:"guides/mrxs.md"};function n(l,e,d,h,c,p){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="_3dhistech-mrxs-slides-in-the-browser" tabindex="-1">3DHISTECH MRXS Slides in the Browser <a class="header-anchor" href="#_3dhistech-mrxs-slides-in-the-browser" aria-label="Permalink to &quot;3DHISTECH MRXS Slides in the Browser&quot;">​</a></h1><p>Open the slides your 3DHISTECH Pannoramic saves, as they are. Nothing to convert, nothing to upload. A large slide starts showing right away, because the viewer reads only the part you look at.</p><p>An MRXS slide is a <code>.mrxs</code> file plus a folder of the same name. Keep them together.</p><p><img src="'+i+'" alt="CMU-2.mrxs open in the viewer, with its label and macro pictures"></p><h2 id="how-it-opens" tabindex="-1">How It Opens <a class="header-anchor" href="#how-it-opens" aria-label="Permalink to &quot;How It Opens&quot;">​</a></h2><ul><li><strong>A folder on your disk</strong>: the <code>.mrxs</code> file with its folder of the same name, in Chrome and Edge. See <a href="./local-files.html#open-a-folder">Local Files</a>.</li><li><strong>One zip made without compression</strong>, in any browser, from your disk or its address. See <a href="./local-files.html#zip-without-compression">Zip Without Compression</a>.</li><li><strong>An address</strong> of the zip or the <code>.mrxs</code> file: <code>https://</code>, <code>s3://</code> or <code>gs://</code>. With the <code>.mrxs</code> link, its folder must sit next to it. See <a href="./remote-urls.html">Remote URLs</a>.</li><li><strong>Private data</strong>, with a private link or a token. See <a href="./authenticated-sources.html">Private Images and Slides</a>.</li></ul><h2 id="what-you-will-see" tabindex="-1">What You Will See <a class="header-anchor" href="#what-you-will-see" aria-label="Permalink to &quot;What You Will See&quot;">​</a></h2><ul><li><strong>The slide.</strong> Zoom from the whole slide down to single cells. Bare glass around the tissue is cropped away.</li><li><strong>Orientation.</strong> The slide appears as the scanner stored it, often turned 90 degrees against other scanners. OpenSlide and QuPath show it the same way.</li><li><strong>Fluorescence.</strong> Three channels, one per filter, with names and colours from the file.</li><li><strong>Label and Macro.</strong> They appear under the title. Click one to enlarge it. A label may show patient details. The viewer shows it and never saves or sends it.</li><li><strong>Compression.</strong> JPEG, PNG and BMP.</li><li><strong>Pixel size and magnification.</strong> Both come from the slide, so measurements read in µm and the zoom bar shows the objective. To set your own, see <a href="./calibration.html">Pixel Size and Magnification</a>.</li></ul><h2 id="if-a-slide-does-not-open" tabindex="-1">If a Slide Does Not Open <a class="header-anchor" href="#if-a-slide-does-not-open" aria-label="Permalink to &quot;If a Slide Does Not Open&quot;">​</a></h2><p>The viewer tells you why.</p><table tabindex="0"><thead><tr><th>What the file has</th><th>What the viewer says</th></tr></thead><tbody><tr><td>A zip made with compression</td><td>The files in this zip are compressed, so they cannot be read in parts. Unzip it and open the folder, or make the zip again without compression (zip -0 -r slide.zip folder).</td></tr><tr><td>Another compression</td><td>This MRXS slide uses a compression the viewer cannot read yet.</td></tr><tr><td>Another layout</td><td>This MRXS slide has a layout the viewer cannot read yet.</td></tr><tr><td>A damaged or incomplete slide</td><td>This MRXS slide looks damaged or incomplete.</td></tr></tbody></table><h2 id="annotations" tabindex="-1">Annotations <a class="header-anchor" href="#annotations" aria-label="Permalink to &quot;Annotations&quot;">​</a></h2><p>Import GeoJSON or OME-XML, and export both, from the <strong>Annotations</strong> panel. Send a link that opens the slide with its annotations. <a href="./annotation-exchange.html">Exchanging Annotations</a> shows how. To draw, measure and label shapes on the slide, see <a href="./annotations.html">Annotations</a>.</p><h2 id="public-slides-to-try" tabindex="-1">Public Slides to Try <a class="header-anchor" href="#public-slides-to-try" aria-label="Permalink to &quot;Public Slides to Try&quot;">​</a></h2><p><a href="https://openslide.org" target="_blank" rel="noreferrer">OpenSlide</a> shares test slides in its <a href="https://openslide.cs.cmu.edu/download/openslide-testdata/Mirax/" target="_blank" rel="noreferrer">Mirax folder</a>. Download a slide, then drop it on the viewer. They are CC0. Unpack the zip, or <a href="./local-files.html#zip-without-compression">make it again without compression</a>.</p><h2 id="for-your-it-team" tabindex="-1">For Your IT Team <a class="header-anchor" href="#for-your-it-team" aria-label="Permalink to &quot;For Your IT Team&quot;">​</a></h2><p>To open a slide by address, the server must answer byte-range requests and allow them through <a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/CORS" target="_blank" rel="noreferrer">CORS</a>. For a bucket, allow <code>GET</code> and the <code>Range</code> header in its CORS rules. <a href="./remote-urls.html#what-the-server-needs">What the Server Needs</a> has the details.</p><p>When a server cannot send parts of a file, the viewer says so. Download the slide and open it from your computer.</p><p>Addresses that start with <code>s3://</code> and <code>gs://</code> work too.</p><h2 id="image-credits" tabindex="-1">Image credits <a class="header-anchor" href="#image-credits" aria-label="Permalink to &quot;Image credits&quot;">​</a></h2><p>The screenshot uses <code>CMU-2.mrxs</code> from the OpenSlide test data, CC0. See <a href="./../sample-data.html">Sample Data and Credits</a>.</p><h2 id="privacy" tabindex="-1">Privacy <a class="header-anchor" href="#privacy" aria-label="Permalink to &quot;Privacy&quot;">​</a></h2><p>The slide is read in your browser. Opening one counts as one opened image of the kind &quot;3DHISTECH MRXS slide&quot;. The file name and address are never recorded. See the <a href="https://find-nuclei.github.io/privacy.html" target="_blank" rel="noreferrer">privacy policy</a>.</p><p><small>Product names are trademarks of their owners. Find Nuclei is not affiliated with them.</small></p>',24)])])}const f=t(s,[["render",n]]);export{u as __pageData,f as default};
